#include <set>

class string_buf;

class stringx
{
protected:
  char* chars;
  string_buf* my_buf;

public:
  ~stringx();
};

bool operator<( const stringx& lhs, const stringx& rhs );

class vr_billboard
{
public:
  virtual ~vr_billboard();
};

template <class T>
class instance_bank
{
public:
  struct ref_t
  {
    stringx label;
    T* ptr;
    unsigned int count;
  };

  class less_by_label : public binary_function<const ref_t*,const ref_t*,bool>
  {
  public:
    bool operator()(const ref_t* a,const ref_t* b) const
    {
      return ( a->label < b->label );
    }
  };

  class less_by_ptr : public binary_function<const ref_t*,const ref_t*,bool>
  {
  public:
    bool operator()(const ref_t* a,const ref_t* b) const
    {
      return ( a->ptr < b->ptr );
    }
  };

  typedef set<ref_t*,less_by_label,__malloc_alloc_template<0> > lref_set;
  typedef set<ref_t*,less_by_ptr,__malloc_alloc_template<0> > pref_set;

  lref_set refs_by_label;
  pref_set refs_by_ptr;

  void purge();
};

template <class T>
void instance_bank<T>::purge()
{
  lref_set::iterator i = refs_by_label.begin();
  lref_set::iterator i_end = refs_by_label.end();

  while(i != i_end)
  {
    lref_set::iterator del = i;
    ++i;

    #if defined(DEBUG) && 0
    debug_print("%s ptr=%p",(*del)->label.c_str(),(*del)->ptr);
    #endif
    delete (*del)->ptr;
    delete *del;
  }
/*
  for ( i=refs_by_label.begin(); i!=refs_by_label.end(); ++i )
  {
    delete (*i)->ptr;
    delete *i;
  }
*/
  // unlike erase(), these functions should deallocate the sets

  // PEH TEST
/*   refs_by_label = lref_set(); */
/*   refs_by_ptr   = pref_set(); */
  refs_by_label.clear();
  refs_by_ptr.clear();
}

template void instance_bank<vr_billboard>::purge();
